questions.prompt:
کدام خط خطای کامپایل دارد؟
`{ int score = 10; }
System.out.println(score);`

کدام خط علت خطا است؟
`final String code="A";
code="B";`

کدام خط خطای کامپایل دارد؟
if (true) { int score = 8; }
System.out.println(score);

نتیجهٔ کامپایل این کد چیست؟
int age;
System.out.println(age);

خروجی چیست؟
int n = 1;
{ int n2 = n + 2; System.out.print(n2); }

نتیجهٔ این کد چیست؟
boolean ok = false;
int x;
if (ok) x = 1;
System.out.println(x);

نتیجهٔ کد زیر چیست؟
final int limit = 10;
limit = 11;

خروجی چیست؟
final StringBuilder b = new StringBuilder("A");
b.append("B");
System.out.println(b);

خروجی چیست؟
int[] a = {1};
int[] b = a;
b[0] = 9;
System.out.println(a[0]);

خروجی چیست؟
static void rename(StringBuilder x) { x = new StringBuilder("new"); }
StringBuilder name = new StringBuilder("old");
rename(name);
System.out.println(name);

خروجی چیست؟
static void add(StringBuilder x) { x.append("!"); }
StringBuilder name = new StringBuilder("go");
add(name);
System.out.println(name);

بعد از این کد کدام عبارت درست است؟
Object a = new Object();
Object b = a;
a = null;

خروجی چیست؟
StringBuilder a = new StringBuilder("x");
StringBuilder b = a;
b = new StringBuilder("y");
System.out.println(a);

چرا کد زیر برای resource موجود نامعتبر است؟
R r = new R();
r = new R();
try (r) {}

خروجی کد زیر چیست؟
static int f() { try (R r = new R()) { return 4; } }
// R.close() فقط چاپ C می‌کند
System.out.print(f());

خروجی چیست؟
static void change(int n) { n = 9; }
int value = 3;
change(value);
System.out.println(value);

خروجی کد زیر چیست؟
class Counter { static int total = 3; }
System.out.println(Counter.total);

پس از این دو import، استفادهٔ ساده از Date چه نتیجه‌ای دارد؟
import java.util.Date;
import java.sql.Date;

اگر نوع public class زیر com.acme قرار دارد، نام دودویی درست آن چیست؟
package com.acme;
public class Tool {}

برای کد زیر کدام موارد درست‌اند؟
package shop;
import java.util.List;
public class Cart { }
